"""Streaming character tokenizer."""

class StreamTokenizer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def has_next(self) -> bool:
        return self.pos < self.length

    def peek(self) -> str:
        if self.pos < self.length:
            return self.text[self.pos]
        return ""

    def peek_ahead(self, n: int = 1) -> str:
        target = self.pos + n
        if target < self.length:
            return self.text[target]
        return ""

    def advance(self) -> str:
        ch = self.peek()
        self.pos += 1
        return ch

repo_files.csv_parser.py:
"""RFC-4180 streaming CSV table parser."""

from typing import List
from tokenizer import StreamTokenizer


class StreamingCSVParser:
    def parse_rows(self, raw_csv: str) -> List[List[str]]:
        tok = StreamTokenizer(raw_csv)
        rows: List[List[str]] = []
        current_row: List[str] = []
        current_field: list[str] = []
        in_quotes = False

        while tok.has_next():
            ch = tok.advance()

            if ch == '"':
                # BUG: When inside quotes and encountering `""`, it immediately flips in_quotes to False
                # instead of consuming both quotes as a single escaped quote!
                if in_quotes:
                    in_quotes = False
                else:
                    in_quotes = True
            elif ch == "," and not in_quotes:
                current_row.append("".join(current_field))
                current_field = []
            elif ch == "\n" and not in_quotes:
                current_row.append("".join(current_field))
                current_field = []
                rows.append(current_row)
                current_row = []
            elif ch == "\r" and not in_quotes:
                if tok.peek() == "\n":
                    tok.advance()
                current_row.append("".join(current_field))
                current_field = []
                rows.append(current_row)
                current_row = []
            else:
                current_field.append(ch)

        if current_field or current_row:
            current_row.append("".join(current_field))
            rows.append(current_row)

        return rows

